import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Instant;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private final OrderService service = new OrderService(new OrderRepository());

    @Test
    void countsOrdersByWarsawDayNotUtcDay() {
        // October is CEST (UTC+2): 22:30Z on Sep 30 is 00:30 on Oct 1 in Warsaw.
        service.place("c", Money.pln(1), Instant.parse("2026-09-30T22:30:00Z"));
        // 21:30Z on Sep 30 is 23:30 on Sep 30 in Warsaw.
        service.place("c", Money.pln(1), Instant.parse("2026-09-30T21:30:00Z"));
        service.place("c", Money.pln(1), Instant.parse("2026-10-01T12:00:00Z"));

        assertEquals(2, service.placedOn(LocalDate.of(2026, 10, 1)));
        assertEquals(1, service.placedOn(LocalDate.of(2026, 9, 30)));
    }

    @Test
    void usesWinterOffsetInJanuary() {
        // January is CET (UTC+1): 22:30Z on Jan 15 is 23:30 on Jan 15 in Warsaw.
        service.place("c", Money.pln(1), Instant.parse("2026-01-15T22:30:00Z"));
        // 23:30Z on Jan 15 is 00:30 on Jan 16 in Warsaw.
        service.place("c", Money.pln(1), Instant.parse("2026-01-15T23:30:00Z"));

        assertEquals(1, service.placedOn(LocalDate.of(2026, 1, 15)));
        assertEquals(1, service.placedOn(LocalDate.of(2026, 1, 16)));
    }

    @Test
    void zeroWhenNothingPlacedThatDay() {
        assertEquals(0, service.placedOn(LocalDate.of(2026, 5, 5)));
    }
}
}
